import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, color, mix, fract, sin, dot, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, DirectionalLight, Box3 } = ctx.THREE;

  const root = new Group();
  const timelines = [];
  const primitiveRuns = [];

  // --- text extraction ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role) => {
    const r = role.toLowerCase();
    const it = items.find((x) => (x.role || '').toLowerCase() === r);
    return it?.text ?? '';
  };
  const heroStr = findText('hero') || 'TIME, MACHINED.';
  const subStr = findText('subhead') || 'Every calibre begins as a solid billet.';
  const capStr = findText('caption') || 'NOVA ATELIER / CALIBRE PROGRAM';

  // --- helpers ---
  const setGroupOpacity = (obj, val) => {
    obj.traverse((o) => {
      if (o.isMesh && o.material) {
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        mats.forEach((m) => {
          m.transparent = true;
          m.opacity = val;
          m.needsUpdate = true;
        });
      }
    });
  };

  // --- backdrop: engineered gradient + mono grain ---
  const v = uv();
  const grain = fract(mul(sin(dot(v, vec2(12.9898, 78.233))), 43758.5453));
  const grad = mix(color('#0b0b10'), color('#13131a'), v.y);
  const backdropColor = mix(grad, vec3(grain), 0.015);
  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: backdropColor,
    side: ctx.THREE.DoubleSide,
  });
  const backdrop = new ctx.THREE.Mesh(new PlaneGeometry(8.0, 6.0), backdropMat);
  backdrop.position.set(0, 0, -1.5);
  root.add(backdrop);

  // --- local lights (rim + key for the underline / any PBR accents) ---
  const keyLight = new DirectionalLight('#e8ecf2', 1.2);
  keyLight.position.set(3, 4, 5);
  root.add(keyLight);

  const rimLight = new DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-4, 2, -3);
  root.add(rimLight);

  const fillLight = new DirectionalLight('#e8ecf2', 0.35);
  fillLight.position.set(-3, -2, 4);
  root.add(fillLight);

  // --- caption kicker ---
  const caption = ctx.fontAtlas.createText(capStr, {
    fontSize: 0.09,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2,
  });
  caption.position.set(0, 1.15, 0.25);
  setGroupOpacity(caption, 0);
  root.add(caption);

  // --- hero: per-word dimensional type with parallax depth ---
  const heroGroup = new Group();
  const words = heroStr.split(' ').filter(Boolean);
  const wordMeshes = words.map((w, i) => {
    const m = ctx.fontAtlas.createText(w, {
      fontSize: 0.62,
      color: '#e8ecf2',
      align: 'center',
    });
    // front-to-back parallax, interpolating across available words
    const t = words.length > 1 ? i / (words.length - 1) : 0;
    m.position.z = 0.12 - t * 0.24;
    return m;
  });

  const box = new Box3();
  const widths = wordMeshes.map((m) => {
    box.setFromObject(m);
    return Math.max(0.001, box.max.x - box.min.x);
  });
  const wordGap = 0.14;
  const totalW = widths.reduce((a, b) => a + b, 0) + wordGap * Math.max(0, words.length - 1);
  let cursor = -totalW / 2;
  wordMeshes.forEach((m, i) => {
    m.position.x = cursor + widths[i] / 2;
    cursor += widths[i] + wordGap;
    heroGroup.add(m);
  });
  heroGroup.position.set(0, 0.4, 0);
  heroGroup.scale.setScalar(1.04);
  root.add(heroGroup);

  // --- apply kinetic-text primitive ---
  const kineticParams =
    config.cinematicPrimitives?.find((p) => p.name === 'kinetic-text')?.params ?? {
      staggerMs: 60,
      riseUnits: 0.35,
    };
  const kineticRun = ctx.primitives['kinetic-text'](heroGroup, kineticParams);
  if (kineticRun) primitiveRuns.push(kineticRun);
  if (kineticRun?.timeline) timelines.push(kineticRun.timeline);

  // --- accent underline rule ---
  const ruleW = 2.6;
  const ruleH = 0.045;
  const ruleGeo = new PlaneGeometry(ruleW, ruleH);
  ruleGeo.translate(ruleW / 2, 0, 0); // anchor left
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    colorNode: color('#ff2a38'),
    emissive: '#ff2a38',
    emissiveNode: color('#ff2a38'),
    emissiveIntensity: 1.2,
    roughness: 0.5,
    metalness: 0.1,
  });
  const rule = new ctx.THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(-ruleW / 2, -0.05, 0.18);
  rule.scale.set(0, 1, 1);
  root.add(rule);

  // --- subhead ---
  const subhead = ctx.fontAtlas.createText(subStr, {
    fontSize: 0.2,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 900,
  });
  subhead.position.set(0, -0.85, 0.12);
  setGroupOpacity(subhead, 0);
  root.add(subhead);

  // --- orchestrated entrance timeline ---
  const allGlyphs = heroStr.split('').filter((c) => c !== ' ').length;
  const glyphStagger = (kineticParams.staggerMs ?? 60) / 1000;
  const kineticEnd = (Math.max(1, allGlyphs) - 1) * glyphStagger + 0.7;
  const settleStart = kineticEnd;
  const underlineStart = settleStart + 0.12;

  const masterTl = gsap.timeline();
  timelines.push(masterTl);

  // caption fade-up
  const captionProxy = { opacity: 0 };
  masterTl.fromTo(
    caption.position,
    { y: 1.08 },
    { y: 1.15, duration: 0.5, ease: 'power2.out' },
    0.2
  );
  masterTl.fromTo(
    captionProxy,
    { opacity: 0 },
    {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => setGroupOpacity(caption, captionProxy.opacity),
    },
    0.2
  );

  // subhead fade-up
  const subProxy = { opacity: 0 };
  masterTl.fromTo(
    subhead.position,
    { y: -0.85 },
    { y: -0.65, duration: 0.5, ease: 'power2.out' },
    0.5
  );
  masterTl.fromTo(
    subProxy,
    { opacity: 0 },
    {
      opacity: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => setGroupOpacity(subhead, subProxy.opacity),
    },
    0.5
  );

  // hero weighted settle
  masterTl.fromTo(
    heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    settleStart
  );

  // underline reveal
  masterTl.to(
    rule.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    underlineStart
  );

  // subtle idle breathing after entrance
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true, paused: true });
  idleTl.to(heroGroup.scale, { x: 1.01, y: 1.01, z: 1.01, duration: 3, ease: 'sine.inOut' });
  timelines.push(idleTl);
  masterTl.eventCallback('onComplete', () => idleTl.play(0));

  // --- handlers & cleanup ---
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl?.kill());
    primitiveRuns.forEach((p) => p?.cleanup?.());
    root.traverse((o) => {
      if (o.geometry) {
        try { o.geometry.dispose(); } catch {}
      }
      if (o.material) {
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        mats.forEach((m) => { try { m.dispose(); } catch {} });
      }
    });
    [keyLight, rimLight, fillLight].forEach((l) => { try { l.dispose(); } catch {} });
    backdropMat.dispose();
    ruleMat.dispose();
    ruleGeo.dispose();
  };

  return root;
}
